using System;
using System.Runtime.InteropServices;
using SD = System.Drawing;

// Agent Watch mascot eyes - icons. The same eyes as the header: two vertical pill slits with a soft, lighter
// shaded centre on a rounded tile. Tray icons are drawn here at runtime; AgentWatch.ico (exe, window, taskbar,
// shortcuts) is generated by make_icon.py in this folder and embedded by build.ps1.
namespace AgentWatch
{
    static class EyeIcon
    {
        [DllImport("user32.dll")] static extern bool DestroyIcon(IntPtr h);

        // the multi-size AgentWatch.ico embedded as a resource -> window / taskbar icon
        public static System.Windows.Media.ImageSource WindowIcon()
        {
            using (var st = System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("AgentWatch.ico"))
            {
                var dec = new System.Windows.Media.Imaging.IconBitmapDecoder(st, System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat, System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);
                System.Windows.Media.Imaging.BitmapFrame best = null;
                foreach (var f in dec.Frames) if (best == null || f.PixelWidth > best.PixelWidth) best = f;
                return best;
            }
        }

        // Same mascot as the header and AgentWatch.ico: two vertical pill eyes with a lighter shaded centre on a rounded tile.
        // Design rule: the eyes always keep the shaded centre highlight - never flat solid black.
        public static SD.Icon Tray(SD.Color fill, bool warn)
        {
            const int S = 32;
            using (var bmp = new SD.Bitmap(S, S))
            {
                using (var g = SD.Graphics.FromImage(bmp))
                {
                    g.SmoothingMode = SD.Drawing2D.SmoothingMode.AntiAlias; g.PixelOffsetMode = SD.Drawing2D.PixelOffsetMode.HighQuality;
                    var tileRect = new SD.RectangleF(1, 1, S - 2, S - 2);
                    using (var path = RoundRect(tileRect, 8))
                    {
                        var top = SD.Color.FromArgb(255, Math.Min(255, fill.R + (255 - fill.R) * 2 / 5), Math.Min(255, fill.G + (255 - fill.G) * 2 / 5), Math.Min(255, fill.B + (255 - fill.B) * 2 / 5));
                        using (var b = new SD.Drawing2D.LinearGradientBrush(tileRect, top, fill, 60f)) g.FillPath(b, path);
                        using (var p = new SD.Pen(SD.Color.FromArgb(90, 255, 255, 255), 1f)) g.DrawPath(p, path);
                    }
                    float pw = 7f, ph = 17f, py = warn ? 6f : 7.5f;
                    foreach (float cx in new[] { 11f, 21f })
                    {
                        var r = new SD.RectangleF(cx - pw / 2, py, pw, ph);
                        using (var path = RoundRect(r, pw / 2))
                        using (var b = new SD.Drawing2D.LinearGradientBrush(new SD.RectangleF(r.X - 0.5f, r.Y, r.Width + 1, r.Height), SD.Color.Black, SD.Color.Black, 0f))
                        {
                            var cb = new SD.Drawing2D.ColorBlend(3);
                            cb.Colors = new[] { SD.Color.FromArgb(7, 6, 12), SD.Color.FromArgb(54, 50, 68), SD.Color.FromArgb(7, 6, 12) };
                            cb.Positions = new[] { 0f, 0.5f, 1f };
                            b.InterpolationColors = cb; g.FillPath(b, path);
                        }
                    }
                    if (warn) using (var b = new SD.SolidBrush(SD.Color.White)) g.FillEllipse(b, 13.5f, 25f, 5, 4.5f);
                }
                IntPtr h = bmp.GetHicon();
                var ic = (SD.Icon)SD.Icon.FromHandle(h).Clone(); DestroyIcon(h); return ic;
            }
        }

        static SD.Drawing2D.GraphicsPath RoundRect(SD.RectangleF r, float rad)
        {
            var p = new SD.Drawing2D.GraphicsPath(); float d = rad * 2;
            if (d > r.Width) d = r.Width; if (d > r.Height) d = r.Height;
            p.AddArc(r.X, r.Y, d, d, 180, 90); p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
            p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90); p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
            p.CloseFigure(); return p;
        }
    }
}
